/**
 * role.ts — the single place that turns whatever the server sent into a `Role`.
 *
 * RULE-B8: the role travels in two shapes. The JWT claim carries the numeric code
 * from PROJECT_AUTH.yaml (`role: 1`), while `GET /api/me` carries the
 * internal name (`role: "parent"`). A guard that compares one shape
 * against the other silently denies the user, which reads as "logged in but
 * forbidden" on every hard refresh.
 *
 * Canonical source: PROJECT_AUTH.yaml —
 *   student 0 · parent 1 · teacher 2 · admin 3
 */
import type { Role } from '~/types/auth';

export const ROLE_BY_NUMBER: Record<number, Role> = {
  0: 'student',
  1: 'parent',
  2: 'teacher',
  3: 'admin',
};

export type RoleName = 'student' | 'parent' | 'teacher' | 'admin';

export const ROLE_TO_NUMBER: Record<RoleName, number> = {
  student: 0,
  parent: 1,
  teacher: 2,
  admin: 3,
};

const ROLE_NAMES = Object.keys(ROLE_TO_NUMBER) as RoleName[];

/**
 * Accepts a number (2), a numeric string ("2"), or an internal name
 * ("agency_admin" / "AGENCY_ADMIN"). Returns null for anything else — callers treat
 * null as "not authorised yet", never as a role.
 */
export function normalizeRole(raw: unknown): Role | null {
  if (raw === null || raw === undefined || raw === '') return null;
  if (typeof raw === 'number') return ROLE_BY_NUMBER[raw] ?? null;
  if (typeof raw === 'string') {
    const t = raw.trim();
    if (/^\d+$/.test(t)) return ROLE_BY_NUMBER[Number(t)] ?? null;
    const n = t.toLowerCase().replace(/[\s-]+/g, '_') as RoleName;
    return ROLE_NAMES.includes(n) ? n : null;
  }
  return null;
}

/** The guard predicate: shape-agnostic on BOTH sides of the comparison. */
export function roleAllowed(raw: unknown, allow: Role | Role[]): boolean {
  const role = normalizeRole(raw);
  if (!role) return false;
  const list = Array.isArray(allow) ? allow : [allow];
  return list.some((a) => normalizeRole(a) === role);
}

/** Where a role lands after login. Most-privileged role first. */
export function homeRouteFor(raw: unknown): string {
  const role = normalizeRole(raw);
  switch (role) {
    case 'admin': return '/admin';
    case 'teacher': return '/';
    case 'parent': return '/';
    case 'student': return '/';
    default: return '/login';
  }
}
